import { es } from '../../i18n/es'
import { COMPATIBILITY_CONFIG } from '../compatibility/config'
import type {
  CompatibilityResult,
  Requirement,
  RequirementType,
} from '../compatibility/computeCompatibility'
import type { DemoSkillId } from '../compatibility/demoVacancy'

/**
 * What the landing card shows for a result of the DEMO calculation: verdict, groups and the
 * explanation. Pure functions; the texts come from the resources file. The explanation comes
 * from a template (it is not generated by AI) and the card says so ("Datos y explicación de
 * ejemplo").
 */

export type VerdictKey = keyof typeof es.card.verdict

export interface SkillRow {
  id: DemoSkillId
  name: string
  kind: RequirementType
  evidence: string
}

export interface SkillGroups {
  match: SkillRow[]
  reinforce: SkillRow[]
  missing: SkillRow[]
}

const skillName = (id: string): string => es.card.skills[id as DemoSkillId] ?? id

const listFormat = new Intl.ListFormat('es', { style: 'long', type: 'conjunction' })
const names = (rows: readonly SkillRow[]): string => listFormat.format(rows.map((row) => row.name))

export function verdictFor(result: CompatibilityResult): VerdictKey {
  const { strong, partial } = COMPATIBILITY_CONFIG.verdict
  if (result.insufficient || result.percent === null) return 'insufficient'
  if (result.capped) return 'capped'
  if (result.percent >= strong) return 'strong'
  if (result.percent >= partial) return 'partial'
  return 'low'
}

export function verdictSubFor(result: CompatibilityResult): string {
  switch (verdictFor(result)) {
    case 'insufficient':
      return es.card.verdictSub.insufficient
    case 'capped':
      return es.card.verdictSub.capped(COMPATIBILITY_CONFIG.cap)
    default:
      return es.card.verdictSub.normal
  }
}

export function buildGroups(
  result: CompatibilityResult,
  requirements: readonly Requirement[],
): SkillGroups {
  const groups: SkillGroups = { match: [], reinforce: [], missing: [] }
  for (const { id, type, credit } of result.credits) {
    const minLevel = requirements.find((req) => req.id === id)?.minLevel ?? 1
    const base = { id: id as DemoSkillId, name: skillName(id), kind: type }
    if (credit >= 1) {
      groups.match.push({ ...base, evidence: es.card.evidence.declared })
    } else if (credit > 0) {
      const level = es.card.minLevel[minLevel] ?? String(minLevel)
      groups.reinforce.push({ ...base, evidence: es.card.evidence.asks(level) })
    } else {
      groups.missing.push({ ...base, evidence: es.card.evidence.notDeclared })
    }
  }
  return groups
}

export function buildExplanation(result: CompatibilityResult, groups: SkillGroups): string {
  const cap = COMPATIBILITY_CONFIG.cap
  if (result.insufficient) return es.card.dora.insufficient

  if (result.capped) {
    const missingRequired = groups.missing.filter((row) => row.kind === 'required')
    return es.card.dora.capped(names(missingRequired), missingRequired.length > 1, cap)
  }

  const parts: string[] = []
  if (groups.match.length > 0) parts.push(es.card.dora.matches(names(groups.match)))
  if (groups.reinforce.length > 0) parts.push(es.card.dora.reinforce(names(groups.reinforce)))
  else if (groups.missing.length > 0) parts.push(es.card.dora.extras(names(groups.missing)))
  else parts.push(es.card.dora.nothingMissing)
  return parts.join(' ')
}
